    }

def search_semantic_scholar_snippets(query, limit=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0407000" if __import__("os").path.isdir("./environment_mix/0407000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _reset_daily_if_needed(client, now_dt):
        try:
            last = client.get("daily_reset_at")
            last_dt = datetime.datetime.fromisoformat(last.replace("Z", "+00:00")).replace(tzinfo=None) if isinstance(last, str) else None
        except Exception:
            last_dt = None
        if last_dt is None or last_dt.date() != now_dt.date():
            client["daily_request_count"] = 0
            client["daily_reset_at"] = _now()

    def _select_client_for_call(clients, now_dt):
        candidates = []
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            if not isinstance(c.get("daily_request_limit"), int) or c.get("daily_request_limit") < 0:
                continue
            if not isinstance(c.get("daily_request_count"), int) or c.get("daily_request_count") < 0:
                continue
            _reset_daily_if_needed(c, now_dt)
            if c["daily_request_count"] + 1 <= c["daily_request_limit"]:
                candidates.append(c)
        if not candidates:
            any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in clients)
            if any_active:
                return ("QUOTA_EXCEEDED", None)
            return ("UNAUTHORIZED", None)
        candidates.sort(key=lambda c: (c["daily_request_limit"] - c["daily_request_count"]), reverse=True)
        return (None, candidates[0])

    def _log_request(tool_requests, client_id, tool_name, status, started_at, query=None, num_results=None,
                     limit=None, paper_id=None, author_id=None, paper_ids=None, author_ids=None,
                     positive_paper_ids=None, negative_paper_ids=None, upstream_http_status=None,
                     upstream_latency_ms=None, error_message=None, result_summary=None, result_payload=None, req_id=None):
        now = _now()
        if req_id is None:
            req_id = _new_id("tr")
        row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status,
            "query": query,
            "num_results": num_results,
            "limit": limit,
            "paper_id": paper_id,
            "author_id": author_id,
            "paper_ids": paper_ids,
            "author_ids": author_ids,
            "positive_paper_ids": positive_paper_ids,
            "negative_paper_ids": negative_paper_ids,
            "upstream_http_status": upstream_http_status,
            "upstream_latency_ms": upstream_latency_ms,
            "error_message": error_message,
            "result_summary": result_summary,
            "result_payload": result_payload,
            "created_at": started_at if status == "received" else now,
            "updated_at": now,
        }
        tool_requests.append(row)
        return row

    def _transition_request(tool_requests, req_id, from_status, to_status, **updates):
        allowed = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                cur = r.get("status")
                if cur != from_status:
                    return _err("INVALID_TRANSITION", f"Cannot transition tool_request from {cur} expecting {from_status}")
                if to_status not in allowed.get(cur, set()):
                    return _err("INVALID_TRANSITION", f"Illegal transition {cur} -> {to_status}")
                r["status"] = to_status
                r["updated_at"] = _now()
                for k, v in updates.items():
                    r[k] = v
                return r
        return _err("NOT_FOUND", "tool_request not found")

    # Validate
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if not q:
        return _err("VALIDATION_ERROR", "query must be non-empty after trimming")

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be in [1, 1000]")

    clients = _load("api_clients.json")
    papers = _load("papers.json")
    tool_requests = _load("tool_requests.json")

    now_dt = datetime.datetime.utcnow()
    code, client = _select_client_for_call(clients, now_dt)
    if code == "QUOTA_EXCEEDED":
        active = next((c for c in clients if isinstance(c, dict) and c.get("status") == "active"), None)
        if active:
            started = _now()
            req = _log_request(
                tool_requests, active.get("id"), "search_semantic_scholar_snippets", "received", started,
                query=q, limit=limit
            )
            _transition_request(tool_requests, req["id"], "received", "failed", error_message="Daily request quota exceeded")
            _save("tool_requests.json", tool_requests)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if code == "UNAUTHORIZED" or client is None:
        return _err("UNAUTHORIZED", "No authorized client available for this request")

    # accept & persist quota increment
    client["daily_request_count"] = int(client.get("daily_request_count") or 0) + 1
    client["updated_at"] = _now()
    _save("api_clients.json", clients)

    started = _now()
    req = _log_request(
        tool_requests, client["id"], "search_semantic_scholar_snippets", "received", started,
        query=q, limit=limit
    )
    tr2 = _transition_request(tool_requests, req["id"], "received", "running")
    if isinstance(tr2, dict) and tr2.get("error"):
        _save("tool_requests.json", tool_requests)
        return tr2

    # Offline snippet search over cached papers only (title + abstract). Do not upsert papers.
    # Simple scoring: count query term occurrences.
    terms = [t for t in re.split(r"\s+", q.lower()) if t]
    def score_text(text):
        if not text:
            return 0
        tl = text.lower()
        return sum(tl.count(t) for t in terms)

    matches = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        title = p.get("title") or ""
        abstract = p.get("abstract") or ""
        s = score_text(title) * 3 + score_text(abstract)
        if s <= 0:
            continue
        # Build a small snippet from abstract
        snippet = None
        if abstract:
            al = abstract.lower()
            idx = min((al.find(t) for t in terms if al.find(t) != -1), default=-1)
            if idx != -1:
                start = max(0, idx - 80)
                end = min(len(abstract), idx + 160)
                snippet = abstract[start:end].strip()
            else:
                snippet = abstract[:240].strip()
        matches.append({
            "paperId": p.get("semantic_scholar_paper_id"),
            "title": p.get("title"),
            "year": p.get("year"),
            "venue": p.get("venue"),
            "url": p.get("url"),
            "snippet": snippet,
            "score": s,
        })

    matches.sort(key=lambda r: (r.get("score", 0), r.get("year") or 0), reverse=True)
    out = matches[:limit]

    latency_ms = int((datetime.datetime.utcnow() - datetime.datetime.fromisoformat(started.replace("Z", "+00:00")).replace(tzinfo=None)).total_seconds() * 1000)
    # Store payload allowed for snippets (may be omitted for size; we store trimmed)
    _transition_request(
        tool_requests, req["id"], "running", "succeeded",
        upstream_http_status=200,
        upstream_latency_ms=max(latency_ms, 0),
        result_summary={"returned": len(out), "scanned_cached_papers": len([p for p in papers if isinstance(p, dict) and p.get("status") == "active"])},
        result_payload={"snippets": out[:50]}  # cap stored payload
    )
    _save("tool_requests.json", tool_requests)

    return {"data": out, "meta": {"limit": limit, "returned": len(out)}}

def get_semantic_scholar_paper_recommendations_from_lists(positive_paper_ids, negative_paper_ids=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0407000" if __import__("os").path.isdir("./environment_mix/0407000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        raw = f"{prefix}:{time.time_ns()}:{os.urandom(8).hex()}"
        return prefix + "_" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:26]

    def _reset_daily_if_needed(c):
        last = _parse_rfc3339(c.get("daily_reset_at"))
        if last is None or last.date() != now_dt.date():
            c["daily_request_count"] = 0
            c["daily_reset_at"] = now_iso

    def _select_client_and_increment(clients):
        any_active = False
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            any_active = True
            if not isinstance(c.get("daily_request_limit"), int) or c["daily_request_limit"] < 0:
                continue
            if not isinstance(c.get("daily_request_count"), int) or c["daily_request_count"] < 0:
                c["daily_request_count"] = 0
            _reset_daily_if_needed(c)
            if c["daily_request_count"] + 1 <= c["daily_request_limit"]:
                c["daily_request_count"] += 1
                c["updated_at"] = now_iso
                return c
        if any_active:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded for all available active clients")
        return _err("UNAUTHORIZED", "No active API client available to serve this request")

    def _log_request(tool_requests, client_id, status, error_message=None, result_summary=None, result_payload=None):
        req_id = _gen_id("ssr")
        row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": "get_semantic_scholar_paper_recommendations_from_lists",
            "status": status,
            "query": None,
            "num_results": None,
            "limit": limit,
            "paper_id": None,
            "author_id": None,
            "paper_ids": None,
            "author_ids": None,
            "positive_paper_ids": list(positive_paper_ids) if isinstance(positive_paper_ids, list) else None,
            "negative_paper_ids": list(negative_paper_ids) if isinstance(negative_paper_ids, list) else None,
            "upstream_http_status": None,
            "upstream_latency_ms": None,
            "error_message": error_message,
            "result_summary": result_summary,
            "result_payload": result_payload,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        return row

    def _transition(tool_requests, req_id, new_status, error_message=None, result_summary=None, result_payload=None, upstream_http_status=None, upstream_latency_ms=None):
        allowed = {"received": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                cur = r.get("status")
                if cur not in allowed or new_status not in allowed[cur]:
                    return _err("INVALID_TRANSITION", f"Illegal tool_requests status transition {cur} -> {new_status}", request_id=req_id)
                r["status"] = new_status
                r["updated_at"] = now_iso
                if error_message is not None:
                    r["error_message"] = error_message
                if result_summary is not None:
                    r["result_summary"] = result_summary
                if result_payload is not None:
                    r["result_payload"] = result_payload
                if upstream_http_status is not None:
                    r["upstream_http_status"] = upstream_http_status
                if upstream_latency_ms is not None:
                    r["upstream_latency_ms"] = upstream_latency_ms
                return r
        return _err("NOT_FOUND", "tool_requests row not found to transition", request_id=req_id)

    def _normalize_paper_row(p):
        return {
            "paper_id": p.get("semantic_scholar_paper_id"),
            "title": p.get("title"),
            "abstract": p.get("abstract"),
            "year": p.get("year"),
            "venue": p.get("venue"),
            "doi": p.get("doi"),
            "url": p.get("url"),
            "citationCount": p.get("citation_count"),
            "referenceCount": p.get("reference_count"),
            "influentialCitationCount": p.get("influential_citation_count"),
            "raw_payload": p.get("raw_payload"),
            "fetched_at": p.get("fetched_at"),
        }

    # Validate (with business rule max=500 for limit and list sizes <=500)
    if not isinstance(positive_paper_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in positive_paper_ids):
        return _err("VALIDATION_ERROR", "positive_paper_ids must be an array of non-empty strings")
    if len(positive_paper_ids) < 1 or len(positive_paper_ids) > 500:
        return _err("VALIDATION_ERROR", "positive_paper_ids length must be between 1 and 500")
    if negative_paper_ids is not None:
        if not isinstance(negative_paper_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in negative_paper_ids):
            return _err("VALIDATION_ERROR", "negative_paper_ids must be an array of non-empty strings when provided")
        if len(negative_paper_ids) > 500:
            return _err("VALIDATION_ERROR", "negative_paper_ids length must be <= 500")
    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

    clients = _load("api_clients.json")
    tool_requests = _load("tool_requests.json")
    papers = _load("papers.json")

    client = _select_client_and_increment(clients)
    if isinstance(client, dict) and "error" in client:
        return client
    if not isinstance(client, dict):
        return _err("UNAUTHORIZED", "No active API client available to serve this request")

    req = _log_request(tool_requests, client.get("id"), "received", result_summary={"stage": "received"})
    req_id = req["id"]
    trans = _transition(tool_requests, req_id, "running", result_summary={"stage": "running"})
    if isinstance(trans, dict) and "error" in trans:
        _save("api_clients.json", clients)
        _save("tool_requests.json", tool_requests)
        return trans

    _save("api_clients.json", clients)
    _save("tool_requests.json", tool_requests)

    # Offline recommendation: pick other cached active papers not in positives/negatives, prefer higher citation_count.
    pos = set([x.strip() for x in positive_paper_ids])
    neg = set([x.strip() for x in (negative_paper_ids or [])])

    eligible = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        upid = p.get("semantic_scholar_paper_id")
        if not isinstance(upid, str) or not upid.strip():
            continue
        if upid in pos or upid in neg:
            continue
        cc = p.get("citation_count")
        cc = cc if isinstance(cc, int) and cc >= 0 else 0
        eligible.append((cc, p))

    eligible.sort(key=lambda x: x[0], reverse=True)
    recs = [_normalize_paper_row(p) for _, p in eligible[:limit]]

    # If there are no eligible papers, succeed with empty list (a read-like outcome, not an error).
    _transition(tool_requests, req_id, "succeeded",
                result_summary={"positive_count": len(pos), "negative_count": len(neg), "returned": len(recs)},
                upstream_http_status=200,
                upstream_latency_ms=0)
    _save("tool_requests.json", tool_requests)

    latency_ms = int((time.time() - t0) * 1000)
    return {"request_id": req_id, "recommendations": recs, "latency_ms": latency_ms}

