            "query": None,
            "num_results": None,
            "limit": None,
            "paper_id": None,
            "author_id": None,
            "paper_ids": None,
            "author_ids": None,
            "positive_paper_ids": None,
            "negative_paper_ids": None,
            "upstream_http_status": None,
            "upstream_latency_ms": None,
            "error_message": error_message,
            "result_summary": result_summary,
            "result_payload": result_payload,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        return row

    def _transition(tool_requests, req_id, new_status, error_message=None, result_summary=None, result_payload=None):
        allowed = {"received": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                cur = r.get("status")
                if cur not in allowed or new_status not in allowed[cur]:
                    return _err("INVALID_TRANSITION", f"Illegal tool_requests status transition {cur} -> {new_status}", request_id=req_id)
                r["status"] = new_status
                r["updated_at"] = now_iso
                if error_message is not None:
                    r["error_message"] = error_message
                if result_summary is not None:
                    r["result_summary"] = result_summary
                if result_payload is not None:
                    r["result_payload"] = result_payload
                return r
        return _err("NOT_FOUND", "tool_requests row not found to transition", request_id=req_id)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")

    clients = _load("api_clients.json")
    tool_requests = _load("tool_requests.json")

    client = _authenticate_client(clients, api_key)
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    quota_err = _enforce_quota_and_increment(client)
    if quota_err:
        return quota_err

    call = _log_call(tool_requests, client.get("id"), "received", result_summary={"stage": "received", "new_status": status})
    call_id = call["id"]
    tr = _transition(tool_requests, call_id, "running", result_summary={"stage": "running", "new_status": status})
    if isinstance(tr, dict) and "error" in tr:
        _save("api_clients.json", clients)
        _save("tool_requests.json", tool_requests)
        return tr

    # Persist acceptance + request lifecycle progression
    _save("api_clients.json", clients)
    _save("tool_requests.json", tool_requests)

    # Enforce lifecycle transitions
    transitions = {"active": {"suspended", "revoked"}, "suspended": {"active", "revoked"}, "revoked": set()}
    cur_status = client.get("status")
    if cur_status not in transitions:
        _transition(tool_requests, call_id, "failed", error_message="Client has invalid current status", result_summary={"current_status": cur_status, "requested_status": status})
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "Client has invalid current status", current_status=cur_status)

    if status == cur_status:
        # Idempotent: allowed, no state change, but still succeeds (tool call had effect in audit/quota log).
        _transition(tool_requests, call_id, "succeeded", result_summary={"updated": False, "status": cur_status})
        _save("tool_requests.json", tool_requests)
        latency_ms = int((time.time() - t0) * 1000)
        return {"request_id": call_id, "client": client, "updated": False, "latency_ms": latency_ms}

    if status not in transitions[cur_status]:
        _transition(tool_requests, call_id, "failed",
                    error_message=f"Invalid transition {cur_status}->{status}",
                    result_summary={"current_status": cur_status, "requested_status": status})
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", f"Invalid transition {cur_status}->{status} (allowed: {sorted(list(transitions[cur_status]))})")

    # Apply change and persist
    client["status"] = status
    client["updated_at"] = now_iso

    _save("api_clients.json", clients)

    _transition(tool_requests, call_id, "succeeded", result_summary={"updated": True, "status": status})
    _save("tool_requests.json", tool_requests)

    latency_ms = int((time.time() - t0) * 1000)
    return {"request_id": call_id, "client": client, "updated": True, "latency_ms": latency_ms}
